import { PASSWORD, expect, test } from "../../fixtures";

test.describe("sign in", () => {
  test("unknown email is rejected the same way as a wrong password", { tag: "@AUTH-03" }, async ({ request }) => {
    const response = await request.post("/api/auth/login", {
      data: { email: "nobody@northwind.test", password: PASSWORD },
    });

    const body = await response.text();
    expect(response.status(), body).toBe(401);
    expect(JSON.parse(body).error.code, body).toBe("invalid_credentials");
  });
});
